// generated by AI (GitHub Copilot, DeepSeek V4 Flash Vision Exp)
import { readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

import { describe, expect, it } from 'vitest';

import {
  decryptDatabase,
  encryptDatabase,
  isPasswordDatabase,
  newSalt,
} from '../../src/crypto/cipher';
import {
  InvalidPasswordError,
  NotAPasswordDatabaseError,
  UnsupportedVersionError,
} from '../../src/crypto/errors';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..', '..');
const dbBytes = new Uint8Array(readFileSync(resolve(root, 'scripts/test.db')));
const password = readFileSync(resolve(root, 'scripts/test.db.password'), 'utf8').trim();

// The verified flat-pack payload of scripts/test.db (doc/crypto.md):
// revision "2", two empty option strings, one account
// name/userId/password/url/notes = test / test / bYxwbP1r / "" / test.
const EXPECTED_PAYLOAD =
  '00012' + '0000' + '0000' + '0004test' + '0004test' + '0008bYxwbP1r' + '0000' + '0004test';

const decoder = new TextDecoder();

describe('isPasswordDatabase', () => {
  it('recognises the UPM magic', () => {
    expect(isPasswordDatabase(dbBytes)).toBe(true);
    expect(isPasswordDatabase(new Uint8Array([0x00, 0x01, 0x02]))).toBe(false);
    expect(isPasswordDatabase(new Uint8Array([]))).toBe(false);
  });
});

describe('decryptDatabase', () => {
  it('decrypts scripts/test.db to the verified flat-pack payload', async () => {
    const payload = await decryptDatabase(dbBytes, password);
    expect(payload.length).toBe(53);
    expect(decoder.decode(payload)).toBe(EXPECTED_PAYLOAD);
  });

  it('throws InvalidPasswordError for a wrong password', async () => {
    await expect(decryptDatabase(dbBytes, 'nope')).rejects.toBeInstanceOf(
      InvalidPasswordError,
    );
  });

  it('throws NotAPasswordDatabaseError when the magic is corrupt', async () => {
    const corrupt = dbBytes.slice();
    corrupt[0] = 0x58; // 'U' -> 'X'
    await expect(decryptDatabase(corrupt, password)).rejects.toBeInstanceOf(
      NotAPasswordDatabaseError,
    );
  });

  it('throws UnsupportedVersionError for an unknown version byte', async () => {
    const corrupt = dbBytes.slice();
    corrupt[3] = 0x09;
    await expect(decryptDatabase(corrupt, password)).rejects.toBeInstanceOf(
      UnsupportedVersionError,
    );
  });

  it('still decrypts a v2 file (same crypto, different field charset)', async () => {
    const v2 = dbBytes.slice();
    v2[3] = 0x02;
    const payload = await decryptDatabase(v2, password);
    expect(decoder.decode(payload)).toBe(EXPECTED_PAYLOAD);
  });
});

describe('encryptDatabase', () => {
  it('round-trips to a byte-identical file when reusing the salt', async () => {
    const payload = await decryptDatabase(dbBytes, password);
    const salt = dbBytes.slice(4, 12);
    const rebuilt = await encryptDatabase(payload, password, salt);
    expect(Array.from(rebuilt)).toEqual(Array.from(dbBytes));
  });

  it('rejects a salt of the wrong length', async () => {
    await expect(
      encryptDatabase(new Uint8Array([1]), password, new Uint8Array(4)),
    ).rejects.toThrow();
  });
});

describe('newSalt', () => {
  it('returns 8 random bytes', () => {
    const a = newSalt();
    const b = newSalt();
    expect(a.length).toBe(8);
    expect(b.length).toBe(8);
    expect(Array.from(a)).not.toEqual(Array.from(b));
  });
});
